class Solution:
    def couldHappen(self, washed: List[int], served: List[int]) -> bool:
        n = len(washed)
        pos = [washed.index(x) for x in served]
        for j in range(n):
            last = pos[j]
            for k in range(j + 1, n):
                if pos[k] < pos[j]:
                    if pos[k] > last:
                        return False
                    last = pos[k]
        return True

