class Solution {
    public boolean couldHappen(int[] washed, int[] served) {
        int n = washed.length;
        int[] pos = new int[n];
        for (int j = 0; j < n; j++) for (int i = 0; i < n; i++) if (washed[i] == served[j]) pos[j] = i;
        for (int j = 0; j < n; j++) {
            int last = pos[j];
            for (int k = j + 1; k < n; k++) {
                if (pos[k] < pos[j]) {
                    if (pos[k] > last) return false;
                    last = pos[k];
                }
            }
        }
        return true;
    }
}

