class Solution {
    public boolean couldHappen(int[] washed, int[] served) {
        int[] stack = new int[washed.length];
        int top = 0, j = 0;
        for (int plate : washed) {
            stack[top++] = plate;
            while (top > 0 && stack[top - 1] == served[j]) {
                top--;
                j++;
            }
        }
        return j == served.length;
    }
}

